-- =============================================================================
-- Zuno development seed - GENERATED by scripts/generate-seed-sql.py from
-- supabase/seed/zuno_seed.json. Do not edit by hand; edit the JSON and re-run.
--
-- !!! LOCAL DEVELOPMENT ONLY !!!
-- * Creates sample auth users (organizer owners + one attendee) with *.example
--   e-mail addresses and the placeholder password 'change-me-locally'.
-- * All organizers, people and events are fictional.
-- * Never run this file against a production project.
-- Event dates are resolved relative to now() in Asia/Colombo local time.
-- =============================================================================

set timezone = 'Asia/Colombo';

-- Local date + offset days + local time -> timestamptz (Asia/Colombo).
create or replace function pg_temp.seed_at(p_offset_days integer, p_time text)
returns timestamptz language sql stable as $$
  select (((now() at time zone 'Asia/Colombo')::date + p_offset_days) + p_time::time) at time zone 'Asia/Colombo'
$$;

-- Agenda items with offset_hours/duration_hours -> {starts_at, ends_at, title, detail}.
create or replace function pg_temp.seed_agenda(p_starts timestamptz, p_items jsonb)
returns jsonb language sql stable as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'starts_at', p_starts + make_interval(secs => ((i ->> 'offset_hours')::numeric * 3600)::double precision),
      'ends_at', p_starts + make_interval(secs => (((i ->> 'offset_hours')::numeric + (i ->> 'duration_hours')::numeric) * 3600)::double precision),
      'title', i ->> 'title',
      'detail', i ->> 'detail'
    ) order by ord), '[]'::jsonb)
  from jsonb_array_elements(p_items) with ordinality as t(i, ord)
$$;

