-- -----------------------------------------------------------------------------
insert into public.events (id, organizer_id, category_id, venue_id, title, summary, description, format,
                           starts_at, ends_at, capacity, is_free, university, tags, cover_path, cover_alt,
                           agenda, speakers, refund_policy, online_url, status, seats_taken,
                           creation_fee_paid_at, published_at)
select 'e1000000-0000-4000-8000-000000000001', '6f1d0a3e-1c2b-4d5e-8f90-0a1b2c3d4e01', 'hackathons', '7a2e0b4f-2d3c-4e6f-9a01-1b2c3d4e5f01', 'Climate AI Hackathon', 'Thirty-six hours to build tools for flood and heat resilience', 'Teams of up to four build working prototypes that help Sri Lankan communities prepare for floods, landslides and extreme heat. Mentors from climate research, civic tech and design join throughout the weekend. Meals, Wi-Fi and sleeping space are provided. Bring a laptop, a charger and an open mind.', 'physical',
       s.starts_at, s.starts_at + make_interval(secs => 129600), 240, true, null, array['ai', 'climate', 'python', 'civic tech']::text[], 'seed/climate-ai-hackathon.jpg', 'Abstract painting of rain clouds over green terraces in deep teal and amber',
       pg_temp.seed_agenda(s.starts_at, '[{"offset_hours":0,"duration_hours":1,"title":"Check-in and breakfast","detail":"Collect your badge at the main entrance."},{"offset_hours":1,"duration_hours":1,"title":"Problem statements","detail":"Briefings from climate researchers."},{"offset_hours":2,"duration_hours":30,"title":"Build sprint","detail":"Mentor office hours every three hours."},{"offset_hours":33,"duration_hours":3,"title":"Demos and awards","detail":"Three-minute demos for each team."}]'::jsonb), '[{"name":"Dr. Ishara Gunawardena","role":"Climate data scientist","organization":"Sample Research Lab"},{"name":"Ravindu Jayasinghe","role":"Civic tech lead","organization":"Colombo Builders Collective"}]'::jsonb, 'Free registration. Please cancel at least 24 hours before the start so your seat can go to someone on the waitlist.', null,
       case when s.starts_at + make_interval(secs => 129600) <= now() then 'completed' else 'published' end, 168,
       now() - interval '21 days', now() - interval '14 days'
  from (select pg_temp.seed_at(5, '08:30') as starts_at) s
on conflict (id) do nothing;
