-- -----------------------------------------------------------------------------
-- Development user state: wallet (via a posted ledger top-up so the ledger and
-- the balance agree), monthly allowance usage, registrations, tickets, saved
-- events and a few notifications. Skipped if already seeded.
-- -----------------------------------------------------------------------------
do $seed$
declare
  v_dev uuid := 'b0000000-0000-4000-8000-0000000000aa';
  v_month date := private.colombo_month();
  v_reg uuid;
  v_ticket uuid;
  v_order uuid;
  v_starts timestamptz;
  v_created timestamptz;
begin
  if exists (select 1 from public.registrations where user_id = v_dev) then
    raise notice 'development user already seeded';
    return;
  end if;

  -- Wallet: balance changes only through the ledger.
  insert into public.wallet_ledger (user_id, entry_type, amount_minor, status, reference_type, description)
  values (v_dev, 'topup', 14000, 'posted', 'seed', 'LOCAL DEVELOPMENT seed top-up');

  -- Allowance used this calendar month (Asia/Colombo).
  insert into public.allowance_usage (user_id, month, used) values (v_dev, v_month, 13)
  on conflict (user_id, month) do update set used = excluded.used;

  -- Free registration: swiftui-workshop
  select starts_at into v_starts from public.events where id = 'e1000000-0000-4000-8000-000000000002';
  v_created := least(now() - interval '2 days', v_starts - interval '3 days');
  insert into public.registrations (event_id, user_id, status, kind, used_allowance, allowance_month,
                                    fee_minor, reference, created_at)
  values ('e1000000-0000-4000-8000-000000000002', v_dev, 'confirmed', 'free', true, private.colombo_month(v_created), 0,
          private.generate_registration_reference(), v_created)
  returning id into v_reg;
  insert into public.registration_answers (registration_id, question_id, value)
  select v_reg, (a ->> 'question_id')::uuid, a -> 'value' from jsonb_array_elements('[{"question_id":"20d69f82-756b-5729-9606-1403d1a582b1","value":true}]'::jsonb) a;
  v_ticket := private.issue_ticket(v_reg, 'e1000000-0000-4000-8000-000000000002', v_dev, null, null);
  if private.colombo_month(v_created) <> v_month then
    insert into public.allowance_usage (user_id, month, used) values (v_dev, private.colombo_month(v_created), 1)
    on conflict (user_id, month) do update set used = public.allowance_usage.used + 1;
  end if;
  if v_starts < now() then
    -- Past event: the development user attended.
    update public.tickets set status = 'checked_in', checked_in_at = v_starts + interval '20 minutes' where id = v_ticket;
    insert into public.check_ins (ticket_id, event_id, checked_in_at) values (v_ticket, 'e1000000-0000-4000-8000-000000000002', v_starts + interval '20 minutes');
  else
    insert into public.notifications (user_id, kind, title, body, event_id, data, created_at)
    values (v_dev, 'registration_confirmed', 'You''re registered', 'Native iOS with SwiftUI', 'e1000000-0000-4000-8000-000000000002',
            jsonb_build_object('registration_id', v_reg, 'ticket_id', v_ticket), v_created);
  end if;

  -- Free registration: open-source-day
  select starts_at into v_starts from public.events where id = 'e1000000-0000-4000-8000-000000000012';
  v_created := least(now() - interval '2 days', v_starts - interval '3 days');
  insert into public.registrations (event_id, user_id, status, kind, used_allowance, allowance_month,
                                    fee_minor, reference, created_at)
  values ('e1000000-0000-4000-8000-000000000012', v_dev, 'confirmed', 'free', true, private.colombo_month(v_created), 0,
          private.generate_registration_reference(), v_created)
  returning id into v_reg;
  v_ticket := private.issue_ticket(v_reg, 'e1000000-0000-4000-8000-000000000012', v_dev, null, null);
  if private.colombo_month(v_created) <> v_month then
    insert into public.allowance_usage (user_id, month, used) values (v_dev, private.colombo_month(v_created), 1)
    on conflict (user_id, month) do update set used = public.allowance_usage.used + 1;
  end if;
  if v_starts < now() then
    -- Past event: the development user attended.
    update public.tickets set status = 'checked_in', checked_in_at = v_starts + interval '20 minutes' where id = v_ticket;
    insert into public.check_ins (ticket_id, event_id, checked_in_at) values (v_ticket, 'e1000000-0000-4000-8000-000000000012', v_starts + interval '20 minutes');
  else
    insert into public.notifications (user_id, kind, title, body, event_id, data, created_at)
    values (v_dev, 'registration_confirmed', 'You''re registered', 'Open Source Community Day', 'e1000000-0000-4000-8000-000000000012',
            jsonb_build_object('registration_id', v_reg, 'ticket_id', v_ticket), v_created);
  end if;

  -- Free registration: lagoon-music-night
  select starts_at into v_starts from public.events where id = 'e1000000-0000-4000-8000-000000000016';
  v_created := least(now() - interval '2 days', v_starts - interval '3 days');
  insert into public.registrations (event_id, user_id, status, kind, used_allowance, allowance_month,
                                    fee_minor, reference, created_at)
  values ('e1000000-0000-4000-8000-000000000016', v_dev, 'confirmed', 'free', true, private.colombo_month(v_created), 0,
          private.generate_registration_reference(), v_created)
  returning id into v_reg;
  v_ticket := private.issue_ticket(v_reg, 'e1000000-0000-4000-8000-000000000016', v_dev, null, null);
  if private.colombo_month(v_created) <> v_month then
    insert into public.allowance_usage (user_id, month, used) values (v_dev, private.colombo_month(v_created), 1)
    on conflict (user_id, month) do update set used = public.allowance_usage.used + 1;
  end if;
  if v_starts < now() then
    -- Past event: the development user attended.
    update public.tickets set status = 'checked_in', checked_in_at = v_starts + interval '20 minutes' where id = v_ticket;
    insert into public.check_ins (ticket_id, event_id, checked_in_at) values (v_ticket, 'e1000000-0000-4000-8000-000000000016', v_starts + interval '20 minutes');
  else
    insert into public.notifications (user_id, kind, title, body, event_id, data, created_at)
    values (v_dev, 'registration_confirmed', 'You''re registered', 'Lagoon Music Night', 'e1000000-0000-4000-8000-000000000016',
            jsonb_build_object('registration_id', v_reg, 'ticket_id', v_ticket), v_created);
  end if;

  -- Paid ticket (1 x Lawn): jazz-under-the-stars. Counted inside the tier's seeded `sold`.
  insert into public.orders (user_id, event_id, kind, status, subtotal_minor, commission_minor, total_minor,
                             idempotency_key, answers, expires_at, paid_at, created_at)
  values (v_dev, 'e1000000-0000-4000-8000-000000000006', 'ticket', 'paid', 300000, (300000 * private.setting('commission_bps') + 5000) / 10000, 300000,
          'seed-jazz-under-the-stars-dev', '[]'::jsonb, now() - interval '6 days 23 hours', now() - interval '7 days', now() - interval '7 days')
  returning id into v_order;
  insert into public.order_items (order_id, tier_id, quantity, unit_price_minor) values (v_order, 'f1000000-0000-4000-8000-000000000061', 1, 300000);
  insert into public.payments (order_id, provider_payment_id, status_code, amount_minor, currency, method, outcome, notification)
  values (v_order, 'seed-jazz-under-the-stars', 2, 300000, 'LKR', 'TEST', 'paid', '{"note":"LOCAL DEVELOPMENT seed payment","status_code":"2"}'::jsonb);
  insert into public.registrations (event_id, user_id, status, kind, order_id, reference, created_at)
  values ('e1000000-0000-4000-8000-000000000006', v_dev, 'confirmed', 'paid', v_order, private.generate_registration_reference(), now() - interval '7 days')
  returning id into v_reg;
  v_ticket := private.issue_ticket(v_reg, 'e1000000-0000-4000-8000-000000000006', v_dev, 'f1000000-0000-4000-8000-000000000061', v_order);
  insert into public.notifications (user_id, kind, title, body, event_id, data, created_at)
  values (v_dev, 'ticket_issued', 'Your ticket is ready', 'Jazz Under the Stars', 'e1000000-0000-4000-8000-000000000006',
          jsonb_build_object('order_id', v_order, 'ticket_ids', jsonb_build_array(v_ticket)), now() - interval '7 days');
  -- expected commission for this seed order: 15000

  insert into public.saved_events (user_id, event_id) values (v_dev, 'e1000000-0000-4000-8000-000000000003') on conflict do nothing;
  insert into public.saved_events (user_id, event_id) values (v_dev, 'e1000000-0000-4000-8000-000000000004') on conflict do nothing;
  insert into public.saved_events (user_id, event_id) values (v_dev, 'e1000000-0000-4000-8000-000000000011') on conflict do nothing;

  insert into public.notifications (user_id, kind, title, body, data, created_at)
  values (v_dev, 'general', 'Welcome to Zuno', 'Discover events across Sri Lanka and keep your tickets in one place.',
          '{}'::jsonb, now() - interval '10 days');
end
$seed$;

reset timezone;
